"""Persistent (copy-on-write) ordered containers used by the scheduler.

The branchable engine has to snapshot and restore its *entire* computational
state in constant time, therefore no queue may be represented by a mutable
container: every mutation copies only the nodes on the search path and all
other nodes stay shared with the previous versions.  Checkpoints are then
simply references to a root, and a restore is a pointer assignment.

Two container flavours are provided:

``ByteNode`` tree
    Ordered by an arbitrary comparable key, carrying the number of packets and
    their total byte weight in every subtree.  It backs the per-bank staging
    FIFOs (ordered by arrival ordinal) and the per-bank PIFOs (ordered by
    ``(rank, ordinal)``).

``LiveNode`` tree
    Ordered by ``(rank, ordinal)`` and carrying the number of live packets plus
    the *lag* accounting of every resident.  Lag increments are range updates
    ("every resident with a strictly smaller rank gains one"), which are
    realised with lazy propagation so that a service opportunity never has to
    touch the backlog.
"""

MASK64 = (1 << 64) - 1


class Priorities:
    """Deterministic pseudo random priority source (xorshift style LCG)."""

    __slots__ = ('_state',)

    def __init__(self, seed=0x2545F4914F6CDD1D):
        self._state = seed & MASK64

    def next(self):
        state = (self._state * 6364136223846793005 + 1442695040888963407) & MASK64
        self._state = state
        return state


# ---------------------------------------------------------------------------
# byte weighted ordered container
# ---------------------------------------------------------------------------


class ByteNode:
    __slots__ = ('key', 'prio', 'left', 'right', 'size', 'bsum', 'pkt')

    def __init__(self, key, prio, pkt, left, right, size, bsum):
        self.key = key
        self.prio = prio
        self.left = left
        self.right = right
        self.size = size
        self.bsum = bsum
        self.pkt = pkt


def _bsum(node):
    return node.bsum if node is not None else 0


def _size(node):
    return node.size if node is not None else 0


def byte_size(root):
    return _size(root)


def byte_bytes(root):
    return _bsum(root)


def _bmk(key, prio, pkt, left, right):
    return ByteNode(key, prio, pkt, left, right,
                    1 + _size(left) + _size(right),
                    pkt.length + _bsum(left) + _bsum(right))


def byte_insert(root, key, pkt, prio):
    """Insert ``pkt`` under ``key``; returns the new root."""
    if root is None:
        return ByteNode(key, prio, pkt, None, None, 1, pkt.length)
    if key < root.key:
        left = byte_insert(root.left, key, pkt, prio)
        if left.prio > root.prio:
            middle = left.right
            newright = _bmk(root.key, root.prio, root.pkt, middle, root.right)
            return _bmk(left.key, left.prio, left.pkt, left.left, newright)
        return _bmk(root.key, root.prio, root.pkt, left, root.right)
    right = byte_insert(root.right, key, pkt, prio)
    if right.prio > root.prio:
        middle = right.left
        newleft = _bmk(root.key, root.prio, root.pkt, root.left, middle)
        return _bmk(right.key, right.prio, right.pkt, newleft, right.right)
    return _bmk(root.key, root.prio, root.pkt, root.left, right)


def byte_append(root, key, pkt, prio):
    """Insert a key that is larger than every key already present."""
    if root is None:
        return ByteNode(key, prio, pkt, None, None, 1, pkt.length)
    if root.prio > prio:
        return _bmk(root.key, root.prio, root.pkt, root.left,
                    byte_append(root.right, key, pkt, prio))
    return _bmk(key, prio, pkt, byte_merge(root, None), None)


def byte_merge(left, right):
    """Concatenate two trees whose keys are strictly ordered."""
    if left is None:
        return right
    if right is None:
        return left
    if left.prio > right.prio:
        return _bmk(left.key, left.prio, left.pkt, left.left,
                    byte_merge(left.right, right))
